begin;

-- install: generated by `npm run guide:content` from content/guide/install.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 10,
  "outcome": "Claude Code установлен, вы вошли в аккаунт и провели первый разговор с агентом в своём репозитории.",
  "blocks": [
    {
      "type": "text",
      "text": "Claude Code — агент в терминале. Он работает в папке, где вы его запустили: читает код, запускает команды и правит файлы. Ставится за минуту, и первый день лучше потратить не на правки, а на знакомство."
    },
    {
      "type": "heading",
      "text": "Установка"
    },
    {
      "type": "text",
      "text": "Рекомендуемый способ — официальный установщик: он ставит Claude Code и дальше обновляет его сам."
    },
    {
      "type": "command",
      "code": "curl -fsSL https://claude.ai/install.sh | bash",
      "caption": "macOS, Linux и WSL. В Windows PowerShell: `irm https://claude.ai/install.ps1 | iex`."
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Без sudo",
      "text": "Через npm тоже можно: `npm install -g @anthropic-ai/claude-code`. Но не добавляйте `sudo`: документация прямо предупреждает о проблемах с правами и безопасностью. Homebrew и WinGet работают, только обновлять их придётся вручную."
    },
    {
      "type": "heading",
      "text": "Первый запуск"
    },
    {
      "type": "text",
      "text": "Перейдите в корень проекта и наберите `claude`. В первый раз откроется браузер для входа: подойдёт подписка Claude Pro или Max, аккаунт Claude Console с оплатой API или корпоративный доступ. Дальше вход запоминается."
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция сеанса: разработчик запускает Claude Code в корне своего проекта и спрашивает, что это за проект и как его запустить. Агент сам читает package.json, README и docker-compose, описывает стек и команды запуска и ничего не меняет.",
      "lines": [
        {
          "kind": "command",
          "text": "cd ~/projects/shop && claude",
          "typed": true
        },
        {
          "kind": "meta",
          "text": "Claude Code · вход выполнен"
        },
        {
          "kind": "prompt",
          "text": "Что это за проект и как запустить его локально?",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Читаю package.json, README.md, docker-compose.yml"
        },
        {
          "kind": "info",
          "text": "Node 20, PostgreSQL в Docker, фронтенд на Vite"
        },
        {
          "kind": "info",
          "text": "Запуск: docker compose up -d, затем npm run dev"
        },
        {
          "kind": "prompt",
          "text": "Где лежат тесты и чем их запускать?",
          "typed": true
        },
        {
          "kind": "info",
          "text": "tests/ — Vitest, команда npm test; e2e — npm run e2e"
        },
        {
          "kind": "done",
          "text": "Файлы не менялись: только чтение."
        }
      ]
    },
    {
      "type": "heading",
      "text": "Пять команд первого дня"
    },
    {
      "type": "list",
      "items": [
        "`claude -c` продолжает последний разговор в этой папке, `claude -r` открывает список прошлых.",
        "`/help` показывает все команды; `/` и Tab подсказывают их по мере ввода.",
        "`/init` создаёт черновик CLAUDE.md — памяти проекта. Подробно о нём — в шаге 2.2.",
        "`claude doctor` проверяет установку и настройки, если что-то пошло не так.",
        "`/exit` или дважды Ctrl+D — выход."
      ]
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Сначала вопросы, потом правки",
      "text": "Спросите агента о том, что знаете сами: как запустить проект, где главная логика, как устроены тесты. Так вы быстро поймёте, насколько ему можно доверять. Подробно — в шаге 1.3."
    }
  ],
  "practice": {
    "task": "Установите Claude Code, войдите и запустите его в корне рабочего проекта. Задайте три вопроса, ответы на которые знаете сами: как запустить проект, где живёт главная бизнес-логика, как устроены тесты.",
    "done": [
      "`claude --version` печатает версию;",
      "агент ответил на три вопроса, и вы сверили ответы с тем, что знаете;",
      "в проекте не изменился ни один файл."
    ]
  },
  "check": {
    "questions": [
      {
        "id": "sudo-install",
        "prompt": "Коллега ставит Claude Code командой `sudo npm install -g @anthropic-ai/claude-code`: без sudo «не хватает прав». Что посоветуете?",
        "options": [
          {
            "id": "native",
            "text": "Поставить официальным установщиком без sudo — он ещё и обновляется сам."
          },
          {
            "id": "sudo-ok",
            "text": "Оставить: sudo — обычный способ поставить глобальный пакет."
          },
          {
            "id": "docker",
            "text": "Запускать Claude Code только внутри Docker."
          }
        ]
      },
      {
        "id": "where-run",
        "prompt": "Где запускать `claude`, чтобы агент понимал ваш проект?",
        "options": [
          {
            "id": "root",
            "text": "В корне репозитория."
          },
          {
            "id": "home",
            "text": "В домашней папке, чтобы видеть все проекты сразу."
          },
          {
            "id": "subfolder",
            "text": "В папке с файлом, который хотите поменять."
          }
        ]
      },
      {
        "id": "continue",
        "prompt": "Вчера вы долго обсуждали с агентом задачу и закрыли терминал. Как продолжить с того же места?",
        "options": [
          {
            "id": "continue",
            "text": "`claude -c` в той же папке."
          },
          {
            "id": "retell",
            "text": "Запустить `claude` и пересказать вчерашний разговор."
          },
          {
            "id": "lost",
            "text": "Никак: история пропадает вместе с терминалом."
          }
        ]
      }
    ]
  }
}$json$::jsonb where step_id = 'install';
insert into private.guide_checks (step_id, key) values ('install', $json${
  "sudo-install": {
    "correct": [
      "native"
    ],
    "why": {
      "native": "Да. Документация прямо предостерегает от `sudo npm install -g`, а нативный установщик решает и вопрос прав, и обновления.",
      "sudo-ok": "Именно так делать не советует документация: глобальная установка под root ведёт к проблемам с правами и рискам безопасности.",
      "docker": "Контейнер пригодится для рискованных режимов, но проблему установки он не решает. Официальный установщик работает без root."
    }
  },
  "where-run": {
    "correct": [
      "root"
    ],
    "why": {
      "root": "Да. Агент работает в папке запуска и её подпапках: из корня он видит весь проект, его настройки и тесты.",
      "home": "Агенту нужен один проект в фокусе. Из домашней папки он не поймёт, о каком коде речь, а доступ к лишнему ни к чему.",
      "subfolder": "Из подпапки агент не увидит остального проекта: конфигурации, тестов, соседних модулей. Запускайте из корня, а файл называйте в запросе."
    }
  },
  "continue": {
    "correct": [
      "continue"
    ],
    "why": {
      "continue": "Да. `-c` продолжает последний разговор в текущей папке, а `claude -r` и `/resume` позволяют выбрать любой из прошлых.",
      "retell": "Можно, но пересказ теряет детали. Разговоры сохраняются: `-c` вернёт вчерашний целиком.",
      "lost": "Не пропадает: сессии сохраняются, их открывают `claude -c`, `claude -r` или `/resume` внутри сессии."
    }
  }
}$json$::jsonb)
on conflict (step_id) do update set key = excluded.key;

-- permissions: generated by `npm run guide:content` from content/guide/permissions.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 14,
  "outcome": "Вы знаете, что агент делает сам, а что — с вашего согласия, выбираете режим под задачу и закрепляете границы проекта в настройках.",
  "blocks": [
    {
      "type": "text",
      "text": "Агент в вашем терминале может то же, что и вы: удалить файл, запушить ветку, прочитать `.env`. Поэтому Claude Code делит действия на те, что выполняет сам, и те, что — только с вашего согласия. Полагаться на умолчания не стоит: границы проекта лучше задать явно."
    },
    {
      "type": "heading",
      "text": "Режимы"
    },
    {
      "type": "text",
      "text": "Режим задаёт общий уровень свободы. Свежие версии Claude Code начинают сессию в режиме **auto**: обычную работу агент делает без вопросов, а отдельный классификатор останавливает рискованное. Если auto недоступен — например, его отключила организация, — сессия начинается в ручном режиме **default**."
    },
    {
      "type": "diagram",
      "name": "permission-modes",
      "caption": "**Shift+Tab** переключает режимы по кругу: из auto в default, затем acceptEdits и plan. `bypassPermissions` попадает в этот круг, только если сессию с ним запустили."
    },
    {
      "type": "heading",
      "text": "О чём спрашивает ручной режим"
    },
    {
      "type": "list",
      "items": [
        "**Без вопросов**: чтение и поиск по проекту, безопасные команды вроде `ls`, `cat`, `grep`, `git status`.",
        "**С вопросом**: правка файлов, остальные команды терминала, запросы в интернет.",
        "**В ответ** можно разрешить один раз, разрешить и больше не спрашивать про такую команду в этом проекте или отказать и сказать, что сделать иначе."
      ]
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "bypassPermissions — только в песочнице",
      "text": "В этом режиме (`--dangerously-skip-permissions`) агент не спрашивает ничего. Документация разрешает его только в изолированной среде — контейнере или виртуальной машине. На рабочей машине с доступом к продакшену — никогда."
    },
    {
      "type": "heading",
      "text": "Правила проекта"
    },
    {
      "type": "text",
      "text": "Режим — грубая настройка. Точная — правила в `.claude/settings.json`: что разрешено всегда, а что запрещено всегда. Файл коммитят, и правила получает вся команда."
    },
    {
      "type": "code",
      "file": ".claude/settings.json",
      "code": "{\n  \"permissions\": {\n    \"allow\": [\n      \"Bash(npm run test *)\",\n      \"Bash(npm run lint)\",\n      \"Bash(git diff *)\"\n    ],\n    \"deny\": [\n      \"Bash(git push *)\",\n      \"Read(./.env)\",\n      \"Read(./secrets/**)\"\n    ]\n  }\n}",
      "caption": "Запрет сильнее разрешения: сначала проверяется `deny`, потом правила с вопросом, потом `allow`. Ваши ответы «больше не спрашивать» сохраняются отдельно, в `.claude/settings.local.json`."
    },
    {
      "type": "text",
      "text": "Посмотреть и поправить действующие правила можно командой `/permissions`. Нужна соседняя папка — добавьте её на время сессии: `/add-dir ../shared`."
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция сеанса в ручном режиме: агент чинит падающий тест. Правку файла он согласует с разработчиком, тесты запускает без вопросов по правилу allow, а попытку пуша блокирует правило deny — пуш агент оставляет разработчику.",
      "lines": [
        {
          "kind": "command",
          "text": "claude --permission-mode default",
          "typed": true
        },
        {
          "kind": "prompt",
          "text": "Почини падающий тест в cart.spec.ts",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Читаю tests/cart.spec.ts и src/cart/total.ts"
        },
        {
          "kind": "meta",
          "text": "Правка src/cart/total.ts — разрешено вами"
        },
        {
          "kind": "edit",
          "text": "src/cart/total.ts",
          "diff": "+3 −1"
        },
        {
          "kind": "pass",
          "text": "npm run test cart — по правилу allow, без вопроса"
        },
        {
          "kind": "info",
          "text": "Следующий шаг: git push origin fix/cart"
        },
        {
          "kind": "meta",
          "text": "Заблокировано правилом deny: Bash(git push *)"
        },
        {
          "kind": "done",
          "text": "Тест проходит. Пуш оставляю вам."
        }
      ]
    }
  ],
  "practice": {
    "task": "Вспомните команды, которые вы чаще всего разрешаете агенту, и вынесите их в `.claude/settings.json` проекта. Запретите то, что агент не должен делать никогда: пуш, чтение секретов, удаление миграций.",
    "done": [
      "в `.claude/settings.json` есть списки `allow` и `deny`;",
      "`/permissions` показывает ваши правила;",
      "в ручном режиме агент запускает тесты без вопросов, а попытка пуша блокируется."
    ]
  },
  "check": {
    "questions": [
      {
        "id": "deny-wins",
        "prompt": "В `allow` есть `Bash(git *)`, в `deny` — `Bash(git push *)`. Агент хочет выполнить `git push`. Что произойдёт?",
        "options": [
          {
            "id": "blocked",
            "text": "Команда будет заблокирована."
          },
          {
            "id": "allowed",
            "text": "Выполнится: `allow` шире и разрешает весь git."
          },
          {
            "id": "asks",
            "text": "Агент спросит вас."
          }
        ]
      },
      {
        "id": "auto-start",
        "prompt": "Вы запустили свежий Claude Code без настроек, и агент сразу правит файлы, ни о чём не спрашивая. Почему?",
        "options": [
          {
            "id": "auto",
            "text": "Сессия началась в режиме auto: обычные действия идут без вопросов, рискованное останавливает классификатор."
          },
          {
            "id": "bypass",
            "text": "Сам включился bypassPermissions."
          },
          {
            "id": "broken",
            "text": "Установка сломана: агент обязан спрашивать о каждой правке."
          }
        ]
      },
      {
        "id": "unknown-service",
        "prompt": "Вы впервые разбираетесь в чужом сервисе и хотите, чтобы агент ничего не менял. Какой режим выбрать?",
        "options": [
          {
            "id": "plan",
            "text": "`plan`"
          },
          {
            "id": "accept-edits",
            "text": "`acceptEdits`"
          },
          {
            "id": "bypass",
            "text": "`bypassPermissions`"
          }
        ]
      },
      {
        "id": "deny-list",
        "prompt": "Что стоит записать в `deny` проекта?",
        "multiple": true,
        "options": [
          {
            "id": "env",
            "text": "`Read(./.env)` — чтение секретов."
          },
          {
            "id": "push",
            "text": "`Bash(git push *)` — пуш без вашего ведома."
          },
          {
            "id": "tests",
            "text": "`Bash(npm run test *)` — запуск тестов."
          },
          {
            "id": "sources",
            "text": "`Read(./src/**)` — чтение исходников."
          }
        ]
      }
    ]
  }
}$json$::jsonb where step_id = 'permissions';
insert into private.guide_checks (step_id, key) values ('permissions', $json${
  "deny-wins": {
    "correct": [
      "blocked"
    ],
    "why": {
      "blocked": "Да. Запреты проверяются первыми: подходящее правило `deny` сильнее любого `allow`.",
      "allowed": "Ширина правила не важна: сначала проверяется `deny`, и он срабатывает.",
      "asks": "Спрашивают о командах, которые не попали ни под одно правило. Эту останавливает `deny`."
    }
  },
  "auto-start": {
    "correct": [
      "auto"
    ],
    "why": {
      "auto": "Да. В свежих версиях auto — стартовый режим. Нужно больше контроля — Shift+Tab переключит на default, а постоянные границы задают правила.",
      "bypass": "Этот режим сам не включается: только флагом при запуске или настройкой. И в обычный круг Shift+Tab он не входит.",
      "broken": "Так ведёт себя ручной режим default. Свежие версии стартуют в auto, если он доступен."
    }
  },
  "unknown-service": {
    "correct": [
      "plan"
    ],
    "why": {
      "plan": "Да. В plan агент читает, ищет и запускает безопасные команды, но не правит исходники.",
      "accept-edits": "Наоборот: в нём агент правит файлы без вопросов.",
      "bypass": "Это режим без вопросов вообще — только для изолированной песочницы и уж точно не для знакомства с чужим кодом."
    }
  },
  "deny-list": {
    "correct": [
      "env",
      "push"
    ],
    "why": {
      "env": "Да. Агенту не нужны боевые ключи, чтобы писать код.",
      "push": "Да. Публиковать изменения — ваше решение.",
      "tests": "Тесты — лучший способ для агента проверить себя. Их как раз разрешают в `allow`.",
      "sources": "Без чтения кода агент бесполезен. Чтение проекта безопасно и по умолчанию идёт без вопросов."
    }
  }
}$json$::jsonb)
on conflict (step_id) do update set key = excluded.key;

-- explore-code: generated by `npm run guide:content` from content/guide/explore-code.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 12,
  "outcome": "Вы используете агента как исследователя: быстро разбираетесь в незнакомом коде и проверяете его ответы, прежде чем им доверять.",
  "blocks": [
    {
      "type": "text",
      "text": "Самый безопасный способ начать работать с агентом — задавать вопросы. Он читает проект быстрее вас: находит файлы, идёт по цепочке вызовов, сводит картину. А вы видите, насколько он точен, ещё до того, как он что-то поменяет."
    },
    {
      "type": "compare",
      "before": {
        "label": "Как спрашивают обычно",
        "text": "Как работает авторизация?",
        "note": "Агент найдёт что-нибудь про авторизацию и перескажет. Что именно он прочитал, непонятно."
      },
      "after": {
        "label": "Как спросить точнее",
        "text": "Опиши путь запроса POST /login от роутера до записи сессии: файлы и функции по порядку. Ничего не меняй.",
        "note": "Ответ — маршрут по коду с конкретными файлами. Каждый пункт можно открыть и проверить."
      }
    },
    {
      "type": "heading",
      "text": "Указывайте файлы через @"
    },
    {
      "type": "text",
      "text": "Наберите `@` и начало пути — Claude Code подскажет файлы. `@src/auth/session.ts` добавит в разговор содержимое файла, `@src/auth` — список файлов папки. Если вы знаете, где ответ, так быстрее, чем ждать, пока агент найдёт его сам."
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция сеанса: разработчик просит описать путь запроса входа. Агент находит роут, сервис и хранилище сессий и называет файлы по порядку. На вопрос о блокировке после пяти неудачных попыток агент отвечает, что такой проверки в коде нет.",
      "lines": [
        {
          "kind": "prompt",
          "text": "Опиши путь POST /login до записи сессии. Ничего не меняй.",
          "typed": true
        },
        {
          "kind": "info",
